namespace app_desktop.Services.WindowsUpdate;

internal static class WubSetupHtmlBuilder
{
	internal static string BuildDocument()
	{
		return "<!doctype html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<meta http-equiv=\"Content-Security-Policy\" content=\"default-src 'none'; img-src https://nestg-assets.local; style-src 'unsafe-inline'; script-src 'unsafe-inline'; base-uri 'none'; form-action 'none'\">\n<title>NestG — Windows Update Blocker</title>\n<style>\n:root { color-scheme: dark; font-family: 'Segoe UI Variable Text', 'Segoe UI', sans-serif; color: #f3f7fb; background: #0d141e; }\n* { box-sizing: border-box; }\nhtml, body { width: 100%; height: 100%; margin: 0; overflow: hidden; }\nbutton { font: inherit; cursor: pointer; }\nbutton:focus-visible, main:focus-visible { outline: 2px solid #8fd3ff; outline-offset: 2px; }\nbutton:disabled { cursor: default; opacity: .5; }\n.window { display: grid; grid-template-rows: 58px minmax(0, 1fr) auto; width: 100%; height: 100%; overflow: hidden; border: 1px solid #34495e; border-radius: 14px; background: radial-gradient(ellipse 80% 55% at 90% 4%, #1b3144 0%, transparent 72%), #0d141e; }\n.titlebar { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 0 18px 0 24px; border-bottom: 1px solid #ffffff0d; user-select: none; }\n.brand { display: flex; align-items: center; gap: 11px; min-width: 0; font-size: 18px; font-weight: 700; letter-spacing: -.3px; }\n.brand img { width: 26px; height: 32px; object-fit: contain; }\n.titlebar-note { margin-left: 10px; padding-left: 14px; border-left: 1px solid #3a4b5c; color: #9fb3c6; font-size: 12px; font-weight: 500; letter-spacing: 0; white-space: nowrap; }\n.close-icon { display: grid; place-items: center; flex: 0 0 40px; width: 40px; height: 40px; padding: 0; border: 0; border-radius: 9px; background: transparent; color: #b4c5d5; }\n.close-icon:hover:not(:disabled) { background: #26394a; color: #fff; }\n.close-icon svg { width: 18px; height: 18px; fill: none; stroke: currentColor; stroke-width: 1.8; }\nmain { min-height: 0; padding: 24px 30px 20px; overflow: auto; scrollbar-gutter: stable; }\n.hero { display: flex; gap: 20px; align-items: flex-start; margin-bottom: 20px; }\n.symbol { display: grid; place-items: center; flex: 0 0 72px; width: 72px; height: 72px; border: 1px solid #6aadd161; border-radius: 18px; background: linear-gradient(150deg, #1e3b50, #192631); box-shadow: inset 0 1px #ffffff14, 0 10px 30px #63b7e812; }\n.symbol svg { width: 40px; height: 40px; fill: none; stroke: #91d6f5; stroke-width: 1.7; stroke-linecap: round; stroke-linejoin: round; }\n.eyebrow { margin: 2px 0 5px; color: #85d2f4; font-size: 11px; font-weight: 750; letter-spacing: 1.4px; }\nh1 { margin: 0; font-size: 28px; line-height: 1.23; letter-spacing: -.7px; font-weight: 700; overflow-wrap: anywhere; }\n.intro { margin: 9px 0 0; color: #b9cad8; font-size: 14px; line-height: 1.5; }\n.status-card { padding: 16px 18px; border: 1px solid #355168; border-radius: 12px; background: #142637; }\n.status-top { display: flex; align-items: center; gap: 10px; margin-bottom: 6px; }\n.status-dot { width: 8px; height: 8px; flex: 0 0 8px; border-radius: 50%; background: #82badc; box-shadow: 0 0 0 4px #82badc18; }\n.status-title { font-size: 13px; font-weight: 700; color: #d7e9f8; }\n.status-copy { margin: 0 0 0 18px; color: #aecadf; font-size: 13px; line-height: 1.5; overflow-wrap: anywhere; }\n.status-card[data-stage=\"ready\"] { border-color: #357b70; background: #16352f; }\n.status-card[data-stage=\"ready\"] .status-dot { background: #77d8bd; }\n.status-card[data-stage=\"failed\"] { border-color: #845c57; background: #302421; }\n.status-card[data-stage=\"failed\"] .status-dot { background: #f2a59a; }\n.status-card[data-stage=\"verifying\"] { border-color: #906f40; background: #342a1d; }\n.status-card[data-stage=\"verifying\"] .status-dot { background: #efc27e; }\n.status-card[data-stage=\"downloading\"] { border-color: #37799e; background: #173348; }\n.status-card[data-stage=\"downloading\"] .status-dot { background: #75c9f2; }\n.progress { margin: 12px 0 0 18px; display: flex; align-items: center; gap: 9px; color: #d1e9f9; font-size: 12px; }\n.progress[hidden] { display: none; }\n.progress-track { flex: 1; height: 6px; overflow: hidden; border-radius: 99px; background: #0b1c2a; }\n.progress-fill { display: block; height: 100%; width: 0; border-radius: inherit; background: #80ceef; transition: width .15s ease-out; }\n.details { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; margin-top: 15px; }\n.detail { min-width: 0; padding: 13px 14px; border: 1px solid #2b3c4c; border-radius: 10px; background: #13202c; }\n.detail strong { display: block; margin-bottom: 4px; color: #ecf4fa; font-size: 12px; }\n.detail p { margin: 0; color: #aebfcd; font-size: 12px; line-height: 1.45; }\n.bridge-error { margin: 12px 0 0; color: #f4b0a7; font-size: 12px; }\nfooter { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 14px 24px; border-top: 1px solid #283d4e; background: #111f2b; }\n.help-links { display: flex; align-items: center; gap: 8px; min-width: 0; flex-wrap: wrap; margin-top: 12px; }\n.help { min-height: 42px; padding: 0 7px; border: 0; background: transparent; color: #acd4ef; font-size: 12px; font-weight: 650; white-space: nowrap; }\n.help:hover:not(:disabled) { color: #fff; text-decoration: underline; }\n.actions { display: flex; gap: 9px; align-items: center; justify-content: flex-end; min-width: 0; margin-left: auto; }\n.actions button { min-height: 42px; padding: 0 16px; border-radius: 8px; font-size: 13px; font-weight: 650; white-space: nowrap; }\n.secondary { border: 1px solid #41566b; background: #203246; color: #e8f2fb; }\n.secondary:hover:not(:disabled) { background: #2b445c; }\n.primary { border: 1px solid #77c5f1; background: #68bce9; color: #092638; box-shadow: inset 0 1px #ffffff5c; }\n.primary:hover:not(:disabled) { background: #90d4f5; }\n::-webkit-scrollbar { width: 7px; }\n::-webkit-scrollbar-thumb { background: #3b5569; border-radius: 8px; }\n@media (max-width: 600px) { .titlebar-note { display: none; } main { padding: 20px; } .details { grid-template-columns: 1fr; } footer { padding: 10px 20px; } .actions { width: 100%; } .help { min-height: 30px; } }\n@media (max-width: 420px) { .hero { gap: 12px; } .symbol { flex-basis: 54px; width: 54px; height: 54px; border-radius: 13px; } .symbol svg { width: 31px; height: 31px; } h1 { font-size: 22px; } .intro { font-size: 13px; } .actions button { flex: 1; padding-inline: 6px; font-size: 12px; } }\n@media (max-height: 430px) { main { padding-top: 14px; padding-bottom: 14px; } .hero { margin-bottom: 14px; } .details { margin-top: 12px; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation-duration: .01ms !important; transition-duration: .01ms !important; } }\n</style>\n</head>\n<body>\n<section class=\"window\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"setup-title\" aria-describedby=\"setup-intro\">\n    <header class=\"titlebar\" data-drag>\n        <div class=\"brand\"><img src=\"https://nestg-assets.local/logo.png\" alt=\"\"><span>NestG</span><span class=\"titlebar-note\">Thiết lập Windows Update Blocker</span></div>\n        <button id=\"window-close\" class=\"close-icon\" type=\"button\" data-action=\"close\" aria-label=\"Đóng cửa sổ WUB\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 6 12 12M18 6 6 18\"/></svg></button>\n    </header>\n    <main tabindex=\"0\" aria-label=\"Thông tin Windows Update Blocker\">\n        <div class=\"hero\">\n            <span class=\"symbol\" aria-hidden=\"true\"><svg viewBox=\"0 0 48 48\"><path d=\"M24 4 8 11v12c0 11 6 17 16 21 10-4 16-10 16-21V11Z\"/><path d=\"M24 14v14M24 34h.01\"/></svg></span>\n            <div><p class=\"eyebrow\">WINDOWS UPDATE BLOCKER</p><h1 id=\"setup-title\">Đang chuẩn bị Windows Update Blocker</h1><p class=\"intro\" id=\"setup-intro\">Một lần gạt công tắc là đủ: NestG tự tải, kiểm tra WUB v1.8 rồi dùng nó để đổi trạng thái Windows Update.</p></div>\n        </div>\n        <section class=\"status-card\" id=\"status-card\" data-stage=\"missing\" role=\"status\" aria-live=\"polite\" aria-atomic=\"true\">\n            <div class=\"status-top\"><span class=\"status-dot\" aria-hidden=\"true\"></span><strong class=\"status-title\" id=\"status-title\">WUB chưa được nhập</strong></div>\n            <p class=\"status-copy\" id=\"status-copy\">NestG sẽ tải và kiểm tra WUB v1.8 từ Sordum.</p>\n            <div class=\"progress\" id=\"progress\" hidden><span class=\"progress-track\"><span class=\"progress-fill\" id=\"progress-fill\"></span></span><span id=\"progress-label\">0%</span></div>\n        </section>\n        <div class=\"details\">\n            <div class=\"detail\"><strong>Đang tải và xác minh</strong><p>Tải WUB không đổi Windows Update.</p></div>\n            <div class=\"detail\"><strong>Tự tiếp tục sau khi tải</strong><p>NestG tự chạy WUB. Windows có thể hỏi quyền UAC.</p></div>\n        </div>\n        <div class=\"help-links\"><button class=\"help\" type=\"button\" data-action=\"official\">Trang WUB ↗</button><button class=\"help\" type=\"button\" data-action=\"license\">Điều khoản Sordum ↗</button></div>\n        <p class=\"bridge-error\" id=\"bridge-error\" role=\"alert\" hidden></p>\n    </main>\n    <footer>\n        <div class=\"actions\"><button id=\"defer\" class=\"secondary\" type=\"button\" data-action=\"close\">Để sau</button><button id=\"choose\" class=\"secondary\" type=\"button\" data-action=\"choose\">Chọn ZIP</button><button id=\"download\" class=\"primary\" type=\"button\" data-action=\"download\">Tải WUB</button></div>\n    </footer>\n</section>\n<script>\n(() => {\n    const bridge = window.chrome?.webview;\n    const card = document.getElementById('status-card');\n    const title = document.getElementById('status-title');\n    const copy = document.getElementById('status-copy');\n    const choose = document.getElementById('choose');\n    const download = document.getElementById('download');\n    const defer = document.getElementById('defer');\n    const windowClose = document.getElementById('window-close');\n    const helps = document.querySelectorAll('.help');\n    function post(action) {\n        try {\n            if (!bridge?.postMessage) throw new Error('Bridge unavailable');\n            if (action === 'choose') choose.disabled = true;\n            if (action === 'download' || action === 'cancel') download.disabled = true;\n            bridge.postMessage(action);\n        } catch {\n            choose.disabled = true;\n            const error = document.getElementById('bridge-error');\n            error.textContent = 'Không kết nối được với NestG. Đóng cửa sổ và thử lại.';\n            error.hidden = false;\n            defer.focus();\n        }\n    }\n    window.__nestgWubSetup = {\n        render(state) {\n            card.dataset.stage = state.stage;\n            title.textContent = state.title;\n            copy.textContent = state.message;\n            choose.disabled = !state.canChoose;\n            download.disabled = !state.canDownload && !state.canCancel;\n            download.dataset.action = state.canCancel ? 'cancel' : 'download';\n            download.textContent = state.canCancel ? 'Hủy tải' : 'Tải WUB';\n            defer.disabled = !state.canClose;\n            defer.textContent = state.closeLabel;\n            windowClose.disabled = !state.canClose;\n            helps.forEach(button => button.disabled = state.busy);\n            const progress = document.getElementById('progress');\n            progress.hidden = state.percent == null;\n            if (state.percent != null) {\n                document.getElementById('progress-fill').style.width = state.percent + '%';\n                document.getElementById('progress-label').textContent = state.percent + '%';\n            }\n        }\n    };\n    bridge?.addEventListener('message', event => window.__nestgWubSetup.render(event.data));\n    document.querySelectorAll('[data-action]').forEach(button => button.addEventListener('click', () => {\n        if (!button.disabled) post(button.dataset.action);\n    }));\n    document.addEventListener('keydown', event => {\n        if (event.key === 'Escape') { event.preventDefault(); if (!defer.disabled) post('close'); }\n    });\n    document.querySelector('[data-drag]').addEventListener('mousedown', event => {\n        if (event.button === 0 && !event.target.closest('button')) post('window:drag');\n    });\n    defer.focus();\n})();\n</script>\n</body>\n</html>";
	}
}
